func load(id: String) async throws -> Summary {     // suspension-capable
    try await client.fetchSummary(id)             // await: suspension point
}

let pending = Task { try await load(id: id) }      // handle: the pending value
let summary = try await pending.value              // read end (cancellable)
pending.cancel()                                   // cooperative cancellation
await withTaskGroup(of: Summary.self) { group in   // structured fan-out
    group.addTask { try await load(id: "other") }
}
